-- PHASE 1: EXPAND
-- Add the new column. Old service version still reads user_name; safe.
ALTER TABLE users ADD COLUMN username VARCHAR(255);

-- New service version: writes to BOTH columns during transition
-- Application code (new version):
--   INSERT INTO users (user_name, username) VALUES (?, ?);
--   UPDATE users SET user_name = ?, username = ? WHERE id = ?;

-- PHASE 2: MIGRATE (backfill)
-- Copy existing data. Run in batches to avoid table locks.
UPDATE users
   SET username = user_name
 WHERE username IS NULL;

-- Add NOT NULL constraint only after backfill is complete.
ALTER TABLE users ALTER COLUMN username SET NOT NULL;

-- PHASE 3: CONTRACT
-- Old service version is fully retired. Now safe to remove old column.
-- Application code (new version): reads/writes only username.
ALTER TABLE users DROP COLUMN user_name;
